import{_ as s,c as t,o as e,a2 as i}from"./chunks/framework.CIiVzG-O.js";const g=JSON.parse('{"title":"macOS 權限","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/permissions.md","filePath":"zh-TW/guide/permissions.md","lastUpdated":1793163976000}'),r={name:"zh-TW/guide/permissions.md"};function n(o,a,p,l,h,d){return e(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="macos-權限" tabindex="-1">macOS 權限 <a class="header-anchor" href="#macos-權限" aria-label="Permalink to &quot;macOS 權限&quot;">​</a></h1><p>為了提供最佳的體驗，NueZip 可能會要求數項 macOS 權限。本頁說明每項權限的用途以及管理方式。</p><h2 id="檔案與資料夾" tabindex="-1">檔案與資料夾 <a class="header-anchor" href="#檔案與資料夾" aria-label="Permalink to &quot;檔案與資料夾&quot;">​</a></h2><p>為了能存取系統上任何位置的壓縮檔，NueZip 需要檔案存取權限。</p><p><strong>用途</strong>：讀取壓縮檔檔案、解壓縮內容，以及建立新壓縮檔。</p><p><strong>管理</strong>：系統設定 → <strong>隱私權與安全性</strong> → <strong>檔案與資料夾</strong></p><p>請在首次啟動時出現提示時授予存取權。您可以隨時管理或撤銷存取權。</p><h2 id="finder-擴充功能" tabindex="-1">Finder 擴充功能 <a class="header-anchor" href="#finder-擴充功能" aria-label="Permalink to &quot;Finder 擴充功能&quot;">​</a></h2><p>NueZip 包含一個 Finder 擴充功能，會新增右鍵選單選項。</p><p><strong>用途</strong>：在 Finder 中右鍵點擊壓縮檔，即可直接解壓縮、壓縮，或使用 NueZip 開啟。</p><p><strong>啟用</strong>：系統設定 → <strong>隱私權與安全性</strong> → <strong>擴充功能</strong> → <strong>Finder 擴充功能</strong> → 啟用 <strong>NueZip</strong></p><h2 id="通知" tabindex="-1">通知 <a class="header-anchor" href="#通知" aria-label="Permalink to &quot;通知&quot;">​</a></h2><p>NueZip 可能會針對長時間執行的操作（批次解壓縮、大型壓縮檔壓縮）顯示通知。</p><p><strong>用途</strong>：在背景操作完成時提醒您。</p><p><strong>管理</strong>：系統設定 → <strong>通知</strong> → <strong>NueZip</strong></p><h2 id="完全磁碟存取權-選用" tabindex="-1">完全磁碟存取權（選用） <a class="header-anchor" href="#完全磁碟存取權-選用" aria-label="Permalink to &quot;完全磁碟存取權（選用）&quot;">​</a></h2><p>若要將壓縮檔解壓縮到系統保護的位置，NueZip 可能會要求完全磁碟存取權。</p><p><strong>用途</strong>：將解壓縮出的檔案寫入使用者資料夾以外的位置。</p><p><strong>管理</strong>：系統設定 → <strong>隱私權與安全性</strong> → <strong>完全磁碟存取權</strong></p><p>此權限為選用，僅在您需要處理全系統範圍的位置時才需要。</p><h2 id="使用終端機重置權限" tabindex="-1">使用終端機重置權限 <a class="header-anchor" href="#使用終端機重置權限" aria-label="Permalink to &quot;使用終端機重置權限&quot;">​</a></h2><p>如果權限對話框被關閉，或狀態不一致，您可以使用 <code>tccutil</code> 重置 macOS 的權限提示：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 重置 NueZip 的權限</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tccutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> All</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.w3cub.nuezip</span></span></code></pre></div><p>執行 <code>tccutil</code> 後，請重新啟動 App 並再次觸發該功能，以重新彈出提示。</p><h2 id="疑難排解" tabindex="-1">疑難排解 <a class="header-anchor" href="#疑難排解" aria-label="Permalink to &quot;疑難排解&quot;">​</a></h2><ul><li>如果通知沒有出現，請檢查是否已授予 <strong>通知</strong> 權限。</li><li>變更權限後，請務必退出並重新開啟 NueZip，讓變更生效。</li></ul><p>如需更多協助，請參閱<a href="./troubleshooting.html">疑難排解指南</a>。</p>`,27)])])}const u=s(r,[["render",n]]);export{g as __pageData,u as default};
